/** An error that is safe to show to the caller. Anything else becomes a generic 500. */
export class AppError extends Error {
  constructor(
    public code: string,
    message: string,
    public status = 400,
    public data?: Record<string, unknown>,
  ) {
    super(message);
  }
}

export const notFound = (what = "Not found") => new AppError("not_found", what, 404);
export const forbidden = (msg = "You do not have permission to do this.") => new AppError("forbidden", msg, 403);
export const unauthorized = () => new AppError("unauthorized", "Please sign in.", 401);
export const invalid = (msg: string, data?: Record<string, unknown>) => new AppError("invalid", msg, 400, data);
