import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { DateTime } from "luxon";
import { BookingExperience } from "@/components/BookingExperience";
import { loadContext } from "@/lib/booking/availability";
import { getAgent, getPublicBusiness } from "@/lib/business";
import { minutesToLabel, WEEKDAYS } from "@/lib/time";
import { aiProviderInfo } from "@/lib/ai/provider";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const b = await getPublicBusiness((await params).slug);
  return { title: b ? `Book at ${b.name}` : "Not found" };
}

export default async function BookingPage({ params }: { params: Promise<{ slug: string }> }) {
  const business = await getPublicBusiness((await params).slug);
  if (!business) notFound();
  const ctx = await loadContext(business.id);
  const agent = await getAgent(business.id);
  const now = DateTime.now().setZone(business.timezone);
  const restaurant = business.type === "restaurant";
  const todayHours = ctx.hours.filter((h) => h.weekday === now.weekday);
  const basic = aiProviderInfo().kind === "basic";

  return (
    <main className="mx-auto max-w-5xl px-4 pb-16 sm:px-5">
      <header className="flex items-center gap-4 py-6">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={business.has_logo ? `/api/logo/${business.id}` : "/logo-192.png"} alt="" width={64} height={64} className="size-16 rounded-2xl bg-white object-contain ring-1 ring-line" />
        <div className="min-w-0">
          <h1 className="text-3xl leading-tight font-extrabold sm:text-4xl">{business.name}</h1>
          <p className="mt-1 text-ink-soft">
            {todayHours.length ? `Open today ${todayHours.map((h) => `${minutesToLabel(h.open_min)}–${minutesToLabel(h.close_min)}`).join(" and ")}` : "Closed today"}
            {business.address ? `. ${business.address}` : ""}
          </p>
        </div>
      </header>
      {business.description && <p className="mb-5 max-w-[42rem] text-ink-soft">{business.description}</p>}

      <BookingExperience
        slug={business.slug} agentName={agent.name} greeting={agent.greeting} aiEnabled={business.ai_enabled} bookingEnabled={business.online_booking_enabled}
        contact={[business.phone, business.contact_email].filter(Boolean).join(" or ")}
        today={now.toISODate()!} maxDate={now.plus({ days: ctx.policies.max_advance_days }).toISODate()!}
        maxParty={ctx.policies.max_party_size} partyWord={restaurant ? "Guests" : "People"}
        services={ctx.services.filter((s) => s.active).map((s) => ({ id: s.id, name: s.name }))}
        suggestions={restaurant ? ["Table for 2 tomorrow evening", "What are your opening hours?", "Change or cancel my booking"] : ["Book for tomorrow morning", "What are your opening hours?", "Change or cancel my booking"]}
      />

      <footer className="mt-8 grid gap-5 text-[15px] text-ink-soft sm:grid-cols-2">
        <div>
          <h2 className="mb-1.5 text-base font-bold text-ink">Opening hours</h2>
          <table><tbody>
            {WEEKDAYS.map((d, i) => {
              const rows = ctx.hours.filter((h) => h.weekday === i + 1);
              return <tr key={d}><th scope="row" className="pr-6 text-left font-medium">{d}</th><td className="tabular">{rows.length ? rows.map((h) => `${minutesToLabel(h.open_min)}–${minutesToLabel(h.close_min)}`).join(", ") : "Closed"}</td></tr>;
            })}
          </tbody></table>
          <p className="mt-1 text-[13px] text-muted">Times are local to {business.timezone.replace(/_/g, " ")}.</p>
        </div>
        <div className="space-y-1.5">
          <h2 className="text-base font-bold text-ink">Good to know</h2>
          {ctx.policies.cancellation_policy && <p>{ctx.policies.cancellation_policy}</p>}
          {ctx.policies.late_policy && <p>{ctx.policies.late_policy}</p>}
          {business.phone && <p>Phone: {business.phone}</p>}
          {business.ai_enabled && <p className="text-[13px] text-muted">{agent.name} is an automated assistant{basic ? " with basic understanding of English" : ""}. It only books times that are really free, and always asks you to confirm first.</p>}
        </div>
      </footer>
    </main>
  );
}
