import { Pool, type PoolClient, type QueryResultRow } from "pg";
import { env } from "./env";

// One pool per process (also survives dev hot reloads).
const g = globalThis as unknown as { __abcPool?: Pool };

export function pool(): Pool {
  if (!g.__abcPool) {
    g.__abcPool = new Pool({ connectionString: env.databaseUrl, max: 10, idleTimeoutMillis: 30_000 });
    g.__abcPool.on("error", (e) => console.error(JSON.stringify({ level: "error", msg: "pg pool error", error: e.message })));
  }
  return g.__abcPool;
}

export type Db = Pick<PoolClient, "query">;

export async function q<T extends QueryResultRow = QueryResultRow>(text: string, params: unknown[] = [], db?: Db): Promise<T[]> {
  const res = await (db ?? pool()).query<T>(text, params as never[]);
  return res.rows;
}

export async function one<T extends QueryResultRow = QueryResultRow>(text: string, params: unknown[] = [], db?: Db): Promise<T | null> {
  const rows = await q<T>(text, params, db);
  return rows[0] ?? null;
}

/** Run fn inside a transaction. Rolls back on any thrown error. */
export async function tx<T>(fn: (db: PoolClient) => Promise<T>): Promise<T> {
  const client = await pool().connect();
  try {
    await client.query("BEGIN");
    const out = await fn(client);
    await client.query("COMMIT");
    return out;
  } catch (e) {
    await client.query("ROLLBACK").catch(() => {});
    throw e;
  } finally {
    client.release();
  }
}

export function pgCode(e: unknown): string | undefined {
  return typeof e === "object" && e !== null && "code" in e ? String((e as { code: unknown }).code) : undefined;
}

export async function closePool() {
  if (g.__abcPool) {
    await g.__abcPool.end();
    g.__abcPool = undefined;
  }
}
